// CURSOR
const dot=document.getElementById('cdot'),ring=document.getElementById('cring');
let mx=0,my=0,rx=0,ry=0;
document.addEventListener('mousemove',e=>{mx=e.clientX;my=e.clientY;dot.style.left=mx+'px';dot.style.top=my+'px'});
(function ar(){rx+=(mx-rx)*.12;ry+=(my-ry)*.12;ring.style.left=rx+'px';ring.style.top=ry+'px';requestAnimationFrame(ar)})();
document.querySelectorAll('a,button,.ah,.fqq,.prh,.loh,.ftab,.tbtn').forEach(el=>{
  el.addEventListener('mouseenter',()=>{ring.style.width='52px';ring.style.height='52px'});
  el.addEventListener('mouseleave',()=>{ring.style.width='36px';ring.style.height='36px'});
});

// CODE BACKGROUND
(function initCode(){
  const bg=document.getElementById('codebg');
  const snips=['const app = express()','async function deploy()','supabase.from("users")','npm run build','git push origin main','React.useState(null)','SELECT * FROM projects','vercel --prod','useEffect(() => {','const router = useRouter()','export default function','type Project = {','await fetch("/api/data")','bcrypt.hash(pwd,10)','jwt.sign(payload,secret)','docker compose up','npm install dependencies','interface User extends Base','const [data,setData] = useState','prisma.project.create({data})','process.env.DATABASE_URL','import { createClient } from supabase','const stripe = Stripe(key)','app.use(cors())','db.query("SELECT * FROM")'];
  for(let i=0;i<28;i++){const el=document.createElement('div');el.className='cline';el.textContent=snips[Math.floor(Math.random()*snips.length)];el.style.cssText='left:'+Math.random()*95+'%;top:'+Math.random()*100+'%;animation-duration:'+(12+Math.random()*25)+'s;animation-delay:'+(-Math.random()*20)+'s;opacity:'+(0.025+Math.random()*0.045);bg.appendChild(el);}
})();

// SCROLL REVEAL
const obs=new IntersectionObserver((entries)=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('vis');obs.unobserve(e.target);}});},{threshold:0.08});
document.querySelectorAll('.reveal,.reveal-l,.reveal-r').forEach(el=>obs.observe(el));

// EXPERTISE BARS (animate on tab switch + on reveal)
function animateBars(){document.querySelectorAll('.exf[data-w]').forEach(b=>{b.style.width=b.dataset.w+'%'});}
const exObs=new IntersectionObserver((entries)=>{if(entries[0].isIntersecting)animateBars();},{threshold:0.2});
const exPanel=document.getElementById('tab-expertise');if(exPanel)exObs.observe(exPanel);

// NAV SCROLL
window.addEventListener('scroll',()=>document.getElementById('nav').classList.toggle('stuck',scrollY>60));

// HAMBURGER
function toggleNav(){document.getElementById('ham').classList.toggle('open');document.getElementById('overlay').classList.toggle('open');document.body.style.overflow=document.getElementById('overlay').classList.contains('open')?'hidden':'';}
function closeNav(){document.getElementById('ham').classList.remove('open');document.getElementById('overlay').classList.remove('open');document.body.style.overflow='';}

// POPUP
function openPopup(){document.getElementById('popup').classList.add('open');document.body.style.overflow='hidden';}
function closePopup(){document.getElementById('popup').classList.remove('open');document.body.style.overflow='';}
document.getElementById('popup').addEventListener('click',function(e){if(e.target===this)closePopup();});
// AUTO-POPUP: fires once per session, 4 seconds after landing
(function(){try{if(!sessionStorage.getItem('popup_seen')){setTimeout(function(){openPopup();sessionStorage.setItem('popup_seen','1');},4000);}}catch(e){}})();

// ACCORDIONS
function toggleA(h){const item=h.closest('.ai'),par=item.parentElement;par.querySelectorAll('.ai.open').forEach(el=>{if(el!==item)el.classList.remove('open')});item.classList.toggle('open');}
function toggleP(h){const item=h.closest('.pri');document.querySelectorAll('#procc .pri.open').forEach(el=>{if(el!==item)el.classList.remove('open')});item.classList.toggle('open');}
function toggleL(h){const item=h.closest('.loi');document.querySelectorAll('.loi.open').forEach(el=>{if(el!==item)el.classList.remove('open')});item.classList.toggle('open');}
function toggleFQ(h){const item=h.closest('.fqi');document.querySelectorAll('.fqi.open').forEach(el=>{if(el!==item)el.classList.remove('open')});item.classList.toggle('open');}

// FILTER TABS
function setF(el){document.querySelectorAll('.ftab').forEach(t=>t.classList.remove('on'));el.classList.add('on');}

// RECOGNITION TABS
function switchT(btn,id){
  document.querySelectorAll('.tbtn').forEach(b=>b.classList.remove('on'));
  document.querySelectorAll('.tpanel').forEach(p=>p.classList.remove('on'));
  btn.classList.add('on');
  document.getElementById('tab-'+id).classList.add('on');
  if(id==='expertise'){setTimeout(animateBars,100);}
}

// TESTIMONIALS
const tests=[
  {q:'"Rachael did not just build what I asked for. She caught three problems I did not even know I had and fixed them before I could see them. That kind of thinking is rare."',n:'Daniel Hughes',r:'CEO, TalentFlow · United Kingdom',av:'DH'},
  {q:'"We went from zero to 12,000 monthly users in four months. Rachael built every part of that platform. I cannot imagine what that timeline would have looked like with anyone else."',n:'Sarah Mensah',r:'Founder, NexaShop · Ghana',av:'SM'},
  {q:'"The documentation alone was worth the project fee. We handed the codebase to our internal team six months later and they understood everything immediately. That never happens."',n:'James Okonkwo',r:'CTO, FinPulse · Africa',av:'JO'},
  {q:'"We hired Rachael after two German developers failed to deliver. She understood the brief on the first call, asked the right questions and shipped on the exact agreed date. Impressive professionalism."',n:'Marcus Hoffmann',r:'CEO, DataBridge GmbH · Berlin',av:'MH'},
  {q:'"The AI integration she built for our customer support cut our ticket volume in half within the first month. The team in London could not believe it was done by one person."',n:'Jennifer Walsh',r:'Head of Product, ClearPath · London',av:'JW'},
  {q:'"Rachael rebuilt our entire platform in eight weeks after our previous agency walked out halfway through the project. It performs better than anything we had before."',n:'Callum Reid',r:'Founder, StayNow · Edinburgh',av:'CR'}
];
let ti=0;
function goT(i){
  ti=i;
  const qt=document.getElementById('qt');
  qt.style.opacity='0';
  setTimeout(()=>{
    qt.textContent=tests[i].q;
    document.getElementById('qn').textContent=tests[i].n;
    document.getElementById('qr').textContent=tests[i].r;
    document.getElementById('qav').textContent=tests[i].av;
    document.querySelectorAll('#tbreak .bdot').forEach((d,idx)=>d.classList.toggle('on',idx===i));
    qt.style.opacity='1';
  },150);
}
function nextT(){goT((ti+1)%tests.length);}
function prevT(){goT((ti-1+tests.length)%tests.length);}
setInterval(nextT,5500);


